create extension if not exists pgcrypto;
create type public.project_status as enum ('draft','published');
create table public.projects(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,subtitle text,year int,description text,introduction text,artist_statement text,closing_statement text,cover_image_url text,requires_age_gate boolean not null default true,status project_status not null default 'draft',sort_order int not null default 0,seo_title text,seo_description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.project_blocks(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,type text not null check(type in('full_width_image','large_image','two_image_grid','three_image_grid','four_image_grid','image_text','text','quote','spacer','video')),content jsonb not null default '{}'::jsonb,sort_order int not null default 0,created_at timestamptz not null default now());
create table public.visitor_access(id uuid primary key default gen_random_uuid(),name text not null,email text not null,project_id uuid not null references public.projects(id) on delete cascade,age_confirmed boolean not null,created_at timestamptz not null default now());
create table public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade);
alter table public.projects enable row level security;alter table public.project_blocks enable row level security;alter table public.visitor_access enable row level security;alter table public.admin_users enable row level security;
create policy "published projects are public" on public.projects for select using(status='published' or auth.uid() in(select user_id from public.admin_users));
create policy "blocks for visible projects" on public.project_blocks for select using(project_id in(select id from public.projects where status='published') or auth.uid() in(select user_id from public.admin_users));
create policy "admins manage projects" on public.projects for all using(auth.uid() in(select user_id from public.admin_users)) with check(auth.uid() in(select user_id from public.admin_users));
create policy "admins manage blocks" on public.project_blocks for all using(auth.uid() in(select user_id from public.admin_users)) with check(auth.uid() in(select user_id from public.admin_users));
create policy "server may record access" on public.visitor_access for insert with check(age_confirmed=true);
create policy "admins read access" on public.visitor_access for select using(auth.uid() in(select user_id from public.admin_users));
insert into public.projects(slug,title,subtitle,year,description,introduction,artist_statement,closing_statement,cover_image_url,requires_age_gate,status,sort_order) values('the-red-room','THE RED ROOM','SELF PORTRAITURE I',2026,'A study in colour, proximity and the private theatre of looking.','The room becomes a body: red, close, impossible to leave unchanged. These images were made in the hour when a private gesture becomes a public image.','The Red Room is a fictional demonstration project. Its abstract placeholder images are intended to be replaced with the artist’s own work.','The image remains after the room has emptied.','/demo/red-room-01.svg',true,'published',1);
insert into public.project_blocks(project_id,type,content,sort_order) select id,'full_width_image','{"images":[{"url":"/demo/red-room-02.svg","alt":"Abstract red field with a dark vertical form","caption":"01 — threshold"}]}',1 from public.projects where slug='the-red-room';
insert into public.project_blocks(project_id,type,content,sort_order) select id,'two_image_grid','{"images":[{"url":"/demo/red-room-03.svg","alt":"Abstract warm red and black composition"},{"url":"/demo/red-room-04.svg","alt":"Abstract close composition in charcoal and red"}]}',2 from public.projects where slug='the-red-room';
insert into public.project_blocks(project_id,type,content,sort_order) select id,'text','{"text":"I wanted the photographs to hold the tension of an encounter: the viewer arrives late, the room is already warm, and the body is present without offering an explanation."}',3 from public.projects where slug='the-red-room';
insert into public.project_blocks(project_id,type,content,sort_order) select id,'image_text','{"text":"A self-portrait is never solitary. It is a rehearsal for being seen.","images":[{"url":"/demo/red-room-05.svg","alt":"Abstract red plane with a small pale shape"}]}',4 from public.projects where slug='the-red-room';
insert into public.project_blocks(project_id,type,content,sort_order) select id,'three_image_grid','{"images":[{"url":"/demo/red-room-06.svg","alt":"Abstract deep red texture"},{"url":"/demo/red-room-07.svg","alt":"Abstract dark room geometry"},{"url":"/demo/red-room-08.svg","alt":"Abstract red and off-white composition"}]}',5 from public.projects where slug='the-red-room';
insert into public.project_blocks(project_id,type,content,sort_order) select id,'quote','{"text":"The image remains after the room has emptied."}',6 from public.projects where slug='the-red-room';
